function REACHABLE-SET(k, q0, step):
    current <- {q0}
    repeat
        next <- current
        for q in current:
            for c in 0..k-1:
                next <- next union { step(q, c) }
        if next = current: return current   # fixed point (<= |Q| rounds)
        current <- next

