function OCCURS(k, q0, step, out, target):
    R <- REACHABLE-SET(k, q0, step)
    return EXISTS q in R with out(q) = target

function ZERO-IN-SEQUENCE(k, q0, step, out):
    return OCCURS(k, q0, step, out, 0)

